# bg = 6, but the loop color 6 might overlap. Filter comps whose cells don't touch image border? Check each comp: is it closed (all its cells form a cycle bounding interior of size >=1 with only bg inside)?
def make_comp(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=set(); col=g[i][j]
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                border=all(g[y][x]==col for y in range(r0,r1+1) for x in range(c0,c1+1) if y==r0 or y==r1 or x==c0 or x==c1)
                # enclosed if bbox strictly inside image and border complete
                enc=r0>0 and c0>0 and r1<h-1 and c1<w-1
                area=(r1-r0+1)*(c1-c0+1)
                out.append(dict(col=col,bbox=(r0,c0,r1,c1),cells=cells,border=border,enclosed=enc,area=area,
                                perim=2*(r1-r0+1+c1-c0+1)-4))
    return out
