            while stack:
                a,b=stack.pop(); cells.add((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<R and 0<=y<C and not seen[x][y] and g[x][y]==col:
                        seen[x][y]=True; stack.append((x,y))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            h=r1-r0-1; w=c1-c0-1
            fill=2 if h>=0 and w>=0 and h%2==0 and w%2==0 else 7
            # only fill bbox cells that were bg? or everything? fill whole inner rectangle
            for x in range(r0+1,r1):
                for y in range(c0+1,c1):
                    if inp_bg_check(x,y,(R,C)): pass
                    if g[x][y]==bg or (h>0 and w>0):
                        o[x][y]=fill
            return None  # placeholder
print(G)
